    // ── MutationContext tests ───────────────────────────────────────

    #[tokio::test]
    async fn mutation_context_auto_populates() {
        // Construct inside an (empty) request scope so `actor` is deterministically
        // `None`: an in-scope read never consults the process-global default actor,
        // which a concurrent test (`current::…default_actor_is_used_only_out_of_scope`)
        // may transiently have set. Avoids a test-isolation race on that global.
        crate::current::scope_request(async {
            let ctx = MutationContext::new(MutationOp::Create);
            assert!(ctx.actor.is_none());
            assert!(ctx.request_id.is_some());
            // UUID v4 format: 8-4-4-4-12 = 36 chars
            assert_eq!(ctx.request_id.as_ref().unwrap().len(), 36);
            assert!(matches!(ctx.op, MutationOp::Create));
            assert!(ctx.invalidate_keys.is_empty());
        })
        .await;
    }

    #[test]
    fn mutation_context_invalidate_pushes_key() {
        let mut ctx = MutationContext::new(MutationOp::Create);
        assert!(ctx.invalidate_keys.is_empty());
        ctx.invalidate("cache:key");
        assert_eq!(ctx.invalidate_keys, vec!["cache:key".to_string()]);
    }

    #[test]
    fn mutation_context_with_actor() {
        let mut ctx = MutationContext::new(MutationOp::Update);
        ctx.actor = Some("user-123".into());
        assert_eq!(ctx.actor.as_deref(), Some("user-123"));
    }

    #[tokio::test]
    async fn mutation_context_seeds_actor_from_ambient_scope() {
        // Inside an (empty) request scope the constructor yields `None`
        // deterministically — an in-scope read never consults the process-global
        // default actor a concurrent test may transiently have set (isolation).
        crate::current::scope_request(async {
            assert!(MutationContext::new(MutationOp::Create).actor.is_none());
        })
        .await;

        // Inside `with_actor(...)` the constructor auto-populates the actor.
        crate::current::with_actor("u1", async {
            let ctx = MutationContext::new(MutationOp::Create);
            assert_eq!(ctx.actor.as_deref(), Some("u1"));
        })
        .await;
    }

    #[test]
    fn mutation_context_carries_scoped_idempotency_key() {
        let mut ctx = MutationContext::new(MutationOp::Create);
        assert!(ctx.idempotency_key.is_none());

        ctx.set_idempotency_key("v2:scoped-http-key");

        assert_eq!(ctx.idempotency_key.as_deref(), Some("v2:scoped-http-key"));
    }

    #[test]
    fn mutation_context_deserializes_without_idempotency_key() {
        let ctx: MutationContext = serde_json::from_value(serde_json::json!({
            "op": "Create",
            "actor": null,
            "request_id": "request-1",
            "now": "2026-05-17T00:00:00Z",
            "invalidate_keys": []
        }))
        .expect("old durable hook payloads should deserialize");

        assert!(ctx.idempotency_key.is_none());
    }

    // ── MutationHooks / NoHooks tests ───────────────────────────────

    #[tokio::test]
    async fn no_hooks_all_methods_are_noop() {
        let hooks: NoHooks<(), (), ()> = NoHooks::default();
        let mut ctx = MutationContext::new(MutationOp::Create);
        let mut new_model = ();
        let model = ();
        let mut draft = UpdateDraft::new(());

        assert!(hooks.before_create(&mut ctx, &mut new_model).await.is_ok());
        assert!(hooks.before_update(&mut ctx, &mut draft).await.is_ok());
        assert!(hooks.before_delete(&mut ctx, &model).await.is_ok());
        assert!(hooks.after_create(&mut ctx, &model).await.is_ok());
        assert!(hooks.after_update(&mut ctx, &model).await.is_ok());
    }

    #[tokio::test]
    async fn no_hooks_commit_variants_are_noop() {
        // after_*_commit variants must also be no-ops on NoHooks
        let hooks: NoHooks<(), (), ()> = NoHooks::default();
        let mut ctx = MutationContext::new(MutationOp::Create);
        let model = ();

        assert!(
            hooks.after_create_commit(&mut ctx, &model).await.is_ok(),
            "after_create_commit must default to Ok(())"
        );
        assert!(
            hooks.after_update_commit(&mut ctx, &model).await.is_ok(),
            "after_update_commit must default to Ok(())"
        );
        assert!(
            hooks.after_delete_commit(&mut ctx, &model).await.is_ok(),
            "after_delete_commit must default to Ok(())"
        );
    }

    #[tokio::test]
    async fn custom_hooks_can_override_commit_variants() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicU32, Ordering};

        static CALLS: AtomicU32 = AtomicU32::new(0);

        #[derive(Clone, Default)]
        struct CountingHooks;

        impl MutationHooks for CountingHooks {
            type Model = ();
            type NewModel = ();
            type UpdateModel = ();

            async fn after_create_commit(
                &self,
                _ctx: &mut MutationContext,
                _record: &Self::Model,
            ) -> AutumnResult<()> {
                CALLS.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }

            async fn after_update_commit(
                &self,
                _ctx: &mut MutationContext,
                _record: &Self::Model,
            ) -> AutumnResult<()> {
                CALLS.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }

            async fn after_delete_commit(
                &self,
                _ctx: &mut MutationContext,
                _record: &Self::Model,
            ) -> AutumnResult<()> {
                CALLS.fetch_add(1, Ordering::SeqCst);
                Ok(())
            }
        }

        CALLS.store(0, Ordering::SeqCst);
        let hooks = CountingHooks;
        let mut ctx = MutationContext::new(MutationOp::Create);
        let model = ();

        hooks.after_create_commit(&mut ctx, &model).await.unwrap();
        hooks.after_update_commit(&mut ctx, &model).await.unwrap();
        hooks.after_delete_commit(&mut ctx, &model).await.unwrap();

        assert_eq!(CALLS.load(Ordering::SeqCst), 3);
        let _ = Arc::new(CountingHooks); // ensure Arc usage works (Clone check)
    }

